mapper.select:
SELECT
    other_bonus.name AS name,
    SUM(payroll_other_bonus.amount) AS amount
FROM payroll_other_bonus
         LEFT JOIN other_bonus
                   ON other_bonus.id = payroll_other_bonus.other_bonus_id
WHERE payroll_other_bonus.payroll_id = #{payrollId}
  AND payroll_other_bonus.employee_id = #{filter.employeeId}
  AND payroll_other_bonus.branch_id IN (1, 2)
GROUP BY other_bonus.name;
